15	/** Keeps the reservations in the database. */
16	public final class ReservationStore {
17	
18	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
19	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
20	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
21	    private static final String EXCLUSION_VIOLATION = "23P01";
22	
23	    private final DataSource dataSource;
24	
25	    public ReservationStore(DataSource dataSource) {
26	        this.dataSource = dataSource;
27	    }
28	
29	    /** Saves a new reservation; the database numbers it. */
30	    Reservation add(NewReservation request, Price price) {
31	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
32	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
33	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
34	        try (Connection connection = dataSource.getConnection();
35	                PreparedStatement statement = connection.prepareStatement(insert)) {
36	            statement.setInt(1, request.roomNumber());
37	            statement.setString(2, request.guest().name());
38	            statement.setString(3, request.guest().email());
39	            statement.setString(4, request.guest().cpf());
40	            statement.setDate(5, Date.valueOf(request.checkIn()));
41	            statement.setDate(6, Date.valueOf(request.checkOut()));
42	            statement.setInt(7, request.guests());
